// Shared shapes for flag data. Generated by scripts/build-data.mjs from the
// Wikidata cache (data/raw) merged with hand-written entries (data/curated).

export type Category =
  | 'sovereign'
  | 'territory'
  | 'historical'
  | 'subdivision'
  | 'ethnic'
  | 'organization'
  | 'military'
  | 'religious'
  | 'local'
  | 'other';

/** 1 = full vexillological entry, 2 = rich, 3 = catalogue (imported only). */
export type Tier = 1 | 2 | 3;

/**
 * How well-founded a stated meaning is:
 * - official: set out in law, constitution or by the adopting body
 * - traditional: long-standing, widely documented interpretation
 * - popular: common folk explanation without an official basis
 */
export type MeaningBasis = 'official' | 'traditional' | 'popular';

export interface FlagColor {
  name: string;
  hex: string;
  /** Colour tag from data/tags.json, used for colour-based quizzes. */
  family: string;
  meaning?: string;
  basis?: MeaningBasis;
}

export interface FlagSymbol {
  name: string;
  description: string;
  meaning?: string;
  basis?: MeaningBasis;
}

export interface HistoryStep {
  from: number | null;
  to: number | null;
  /** Commons filename of that period's flag, when known. */
  image?: string;
  /** Link to another flag record, when the period has its own entry. */
  flagId?: string;
  label: string;
  note?: string;
}

export interface Source {
  title: string;
  url?: string;
}

/** Card-sized record used for lists, search and quizzes. */
export interface FlagSummary {
  id: string;
  name: string;
  /** Commons filename (spaces, not underscores). */
  image: string;
  /** Commons hash path, e.g. "c/c3/Flag_of_France.svg". */
  img: string;
  category: Category;
  tier: Tier;
  from: number | null;
  to: number | null;
  current: boolean;
  country?: string;
  tags?: string[];
}

export interface FlagRecord extends FlagSummary {
  wikidata?: string;
  flagName: string;
  nickname?: string;
  description?: string;
  adopted?: string;
  ratio?: string;
  designer?: string;
  summary?: string;
  /** Paragraphs. */
  origin?: string[];
  colors?: FlagColor[];
  symbols?: FlagSymbol[];
  history?: HistoryStep[];
  facts?: string[];
  /** Extra accepted quiz answers (Wikidata aliases are added automatically). */
  aliases?: string[];
  role?: 'primary' | 'former' | 'variant' | 'other';
  /** Separate periods of use, when a flag was used more than once. */
  periods?: { from: number | null; to: number | null }[];
  /** Descriptive quiz clues that never name the flag's owner. */
  clues?: string[];
  lookalikes?: string[];
  /** Wikidata-sourced extras for catalogue entries. */
  depicts?: string[];
  colorNames?: string[];
  wikipedia?: string;
  sources?: Source[];
  /** Other flags of the same subject (ids), oldest first. */
  related?: string[];
  /** Other subjects that use the same flag image. */
  alsoUsedBy?: string[];
  /** Wikidata item for the flag itself, when one exists. */
  flagItem?: string;
  /** True for hand-written entries in data/curated. */
  curated?: boolean;
  /** Text from English Wikipedia (CC BY-SA 4.0): a flag article, or flag sections of the subject's article. */
  /** Measured colour shares of the image, largest first, e.g. [["red", 0.42], ["white", 0.33]]. */
  palette?: [string, number][];
  wiki?: {
    title: string;
    url: string;
    kind: 'article' | 'section';
    sections: { heading: string; level: number; text: string }[];
  };
  /** Wikimedia Commons file page: description (if informative), licence and author. */
  commons?: {
    description?: string;
    license?: string;
    licenseUrl?: string;
    artist?: string;
  };
}
